        is_valid, error = self.validate_type(p_password, 'p_password', str)
        if not is_valid:
            return error
        
        p_settings = params.get('p_settings', None)
        if p_settings is not None:
            is_valid, error = self.validate_type(p_settings, 'p_settings', dict)
            if not is_valid:
                return error
        
        if p_settings is not None:

            _default_p_minLength = int(8) if 8 !=  ""  else 0
            p_minLength = p_settings.get('p_minLength', _default_p_minLength)
            if p_minLength is not None:
                is_valid, error = self.validate_type(p_minLength, 'p_minLength', int)
                if not is_valid:
                    return error
            
            p_requireSpecialCharacter = p_settings.get('p_requireSpecialCharacter', True)
            if p_requireSpecialCharacter is not None:
                is_valid, error = self.validate_type(p_requireSpecialCharacter, 'p_requireSpecialCharacter', bool)
                if not is_valid:
                    return error
            
            p_specialCharacters = p_settings.get('p_specialCharacters', None)
            if p_specialCharacters is not None:
                is_valid, error = self.validate_type(p_specialCharacters, 'p_specialCharacters', list)
                if not is_valid:
                    return error
            
        return {
            "status_code": 200, 
            "results": {
                "function_name": "PasswordStrengthChecker_validateComplexity",
                "p_password": p_password,
                "p_settings": p_settings
            }
        }

